contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(IOracleProvider newOracle, bool newClosed, uint256 callerSeed) public {
        // Determine whether the test contract is the owner of c.
        // The test contract deployed c, so msg.sender for initialize was this contract;
        // controller().owner() should return this address if the deployment wiring is correct.
        bool ownerIsCaller = (c.owner() == address(this));

        bool oracleReverted;
        bool closedReverted;

        // Only exercise the owner-only paths when the caller is NOT the owner.
        // Otherwise calling them could succeed or fail for unrelated reasons, and the
        // assertion below would not be a general rule.
        require(!ownerIsCaller);

        try c.updateOracle(newOracle) {
            oracleReverted = false;
        } catch {
            oracleReverted = true;
        }

        try c.updateClosed(newClosed) {
            closedReverted = false;
        } catch {
            closedReverted = true;
        }

        assert(oracleReverted && closedReverted);
    }

    receive() external payable {}
}

