contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount1, uint256 amount2) public payable {
        // Precondition: ensure amount2 is strictly greater than amount1 and non-trivial
        require(amount1 < amount2, "amount2 must exceed amount1");
        require(amount1 > 1e18, "amount1 must be > 1 token (avoid zero position)");

        // Open a maker position as the test contract
        UFixed18 openAmount = UFixed18Lib.wrap(amount1);
        c.openMake(openAmount);

        // Record the maker position before attempting an over-sized close
        UFixed18 makerBefore = c.position(address(this)).maker;

        // Attempt to close more than open (amount2 > amount1)
        UFixed18 closeAmount = UFixed18Lib.wrap(amount2);
        bool reverted;
        try c.closeMake(closeAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the maker position after the call
        UFixed18 makerAfter = c.position(address(this)).maker;

        // Rule: the over-close must revert, and the maker position must remain unchanged
        assert(reverted && makerAfter.eq(makerBefore));
    }

    receive() external payable {}
}

