contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint128 amount) public {
        // Any close amount is valid; only drive the contract through its public surface.
        // Setup: make the caller the account by using the same msg.sender throughout.
        // Open a maker position so it can be closed.
        require(true);

        // Read-only observation of the pre-state.
        uint256 beforeVersion = c.latestVersion();
        require(beforeVersion >= 0);

        // Change state: open the maker position. Must be a top-level call.
        c.openMakeFor(address(this), UFixed18.wrap(uint256(amount)));

        // The position was opened, so now close exactly that amount.
        c.closeMakeFor(address(this), UFixed18.wrap(uint256(amount)));

        // General rule: after closing exactly the opened amount, the account holds no maker position.
        uint256 makerAfter = UFixed18.unwrap(c.position(address(this)).maker);
        uint256 takerAfter = UFixed18.unwrap(c.position(address(this)).taker);

        assert(makerAfter == 0 && takerAfter == 0);
    }

    receive() external payable {}
}

