contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool newClosed, uint256 throwaway) public {
        // The product must be initialized; if it is not, the rule is vacuous.
        uint256 versionBefore = c.latestVersion();
        bool closedBefore = c.closed();

        // If no oracle data has ever been synced, the product is not usable and
        // the rule below would only test the uninitialized state.
        if (versionBefore == 0) {
            assert(c.latestVersion() == 0 && !c.closed() && closedBefore == false);
            return;
        }

        bool reverted;
        try c.updateClosed(newClosed) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: updateClosed either reverts (leaving both the latest
        // version and the closed flag unchanged) or succeeds and sets the
        // closed flag to exactly the requested value while (at worst) advancing
        // the settlement version.
        if (reverted) {
            assert(c.closed() == closedBefore);
        } else {
            assert(c.closed() == newClosed);
        }
    }

    receive() external payable {}
}

