        // Maker position is now open; opening a taker position on the same account must revert.
        bool takeReverted = false;
        try c.openTakeFor(account, UFixed18.wrap(takeAmount)) {
            takeReverted = false;
        } catch {
            takeReverted = true;
        }

        assert(takeReverted);
    }

    receive() external payable {}
}

