    function run(UFixed18 amount) public {
        require(amount.gt(UFixed18Lib.ZERO));

        UFixed18 beforeShortfall = c.latestVersion() == 0
            ? UFixed18Lib.ZERO
            : controllerShortfall();

        uint256 versionBefore = c.latestVersion();
        UFixed18 takerFee_ = c.takerFee();

        bool reverted;
        try c.openTake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            if (versionBefore != 0) {
                UFixed18 afterShortfall = controllerShortfall();
                assert(afterShortfall.gte(beforeShortfall));
            } else {
                assert(!amount.isZero());
            }
        } else {
            assert(!amount.isZero());
        }
    }

    function controllerShortfall() private view returns (UFixed18) {
        return IController(c);
    }

    receive() external payable {}
}

